create or replace function public.crm_experiment_report(p_experiment_id uuid) returns jsonb language plpgsql stable security invoker set search_path=public as $$
declare v_user uuid:=auth.uid(); v jsonb;
begin
 if v_user is null then raise exception 'UNAUTHORIZED'; end if;
 if not exists(select 1 from public.crm_experiments where id=p_experiment_id and user_id=v_user) then raise exception 'experiment_not_found'; end if;
 with vars as (select v.id,v.name,v.weight,count(distinct x.subject_key) exposures,count(distinct case when o.outcome='conversion' then o.subject_key end) conversions,coalesce(sum(case when o.outcome='revenue' then o.value else 0 end),0) revenue from public.crm_experiment_variants v left join public.crm_experiment_exposures x on x.variant_id=v.id left join public.crm_experiment_outcomes o on o.variant_id=v.id and o.subject_key=x.subject_key where v.experiment_id=p_experiment_id group by v.id,v.name,v.weight), base as (select * from vars order by case when lower(name) in ('control','baseline','a') then 0 else 1 end,name limit 1), gs as (select coalesce(jsonb_agg(jsonb_build_object('id',g.id,'metric_name',g.metric_name,'metric_type',g.metric_type,'min_sample_size',g.min_sample_size,'max_regression',g.max_regression,'enabled',g.enabled) order by g.metric_name),'[]'::jsonb) data from public.crm_experiment_guardrails g where g.experiment_id=p_experiment_id and g.enabled), result as (select jsonb_agg(jsonb_build_object('id',v.id,'name',v.name,'weight',v.weight,'exposures',v.exposures,'conversions',v.conversions,'conversion_rate',case when v.exposures=0 then 0 else v.conversions::numeric/v.exposures end,'revenue',v.revenue,'is_baseline',v.id=(select id from base)) order by v.name) variants from vars) select jsonb_build_object('experiment_id',p_experiment_id,'baseline_variant_id',(select id from base),'variants',coalesce((select variants from result),'[]'::jsonb),'guardrails',(select data from gs)) into v; return v; end $$;
revoke all on function public.crm_experiment_report(uuid) from public,anon; grant execute on function public.crm_experiment_report(uuid) to authenticated;